WITH session_totals AS (SELECT session_id, COUNT(duration_sec) AS duration_sec_count FROM web_events WHERE event_type NOT IN ('click', 'purchase', 'add_to_cart') GROUP BY session_id) SELECT s.id, s.browser, st.duration_sec_count FROM sessions s LEFT JOIN session_totals st ON s.id = st.session_id WHERE st.duration_sec_count > 10;
